#!name=广告联盟
#!desc=去除常见广告联盟请求
#!author=fmz200
#!homepage=https://github.com/fmz200/wool_scripts

[mitm]
hostname = %APPEND% ad.union.example.com, ads.example.net

[rewrite]
^https?:\/\/ad\.union\.example\.com\/v1\/report reject
^https?:\/\/ads\.example\.net\/pixel reject

[script]
http-request ^https?:\/\/api\.example\.com\/ad\/config script-path=https://raw.githubusercontent.com/fmz200/wool_scripts/main/Scripts/ad-config.js, requires-body=true, timeout=10, tag=广告配置
